import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"4.1 仪表基础知识","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-1-yi-biao-ji-chu-zhi-shi.md","filePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-1-yi-biao-ji-chu-zhi-shi.md","lastUpdated":1793095197000}'),e={name:"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-1-yi-biao-ji-chu-zhi-shi.md"};function r(n,t,s,d,h,c){return i(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="_4-1-仪表基础知识" tabindex="-1">4.1 仪表基础知识 <a class="header-anchor" href="#_4-1-仪表基础知识" aria-label="Permalink to &quot;4.1 仪表基础知识&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电工仪表是电工的&quot;眼睛&quot;——没有仪表,你不知道设备有没有电、电流多大、绝缘好不好。这一节先学仪表的基础知识:怎么分类、什么是准确度、怎么选量程。后面 4.2~4.5 再学具体仪表。</p><h2 id="一、电工仪表的分类" tabindex="-1">一、电工仪表的分类 <a class="header-anchor" href="#一、电工仪表的分类" aria-label="Permalink to &quot;一、电工仪表的分类&quot;">​</a></h2><p>按不同的测量对象和用途,仪表可以这样分:</p><table tabindex="0"><thead><tr><th>分类标准</th><th>类型</th><th>例子</th></tr></thead><tbody><tr><td>按测量对象</td><td>电流表、电压表、功率表、电阻表(欧姆表)、电能表</td><td>测 A、V、W、Ω、kWh</td></tr><tr><td>按被测电流</td><td>直流仪表、交流仪表、交直流两用</td><td>—</td></tr><tr><td>按准确度</td><td>0.5、1.0、1.5、2.5、5.0 级</td><td>数字越小越准</td></tr><tr><td>按结构原理</td><td>磁电式、电磁式、电动式、感应式等</td><td>万用表多为磁电式</td></tr></tbody></table><blockquote><p>💡 <strong>磁电式仪表</strong>:利用&quot;通电线圈在磁场中受力偏转&quot;原理,精度高,但一般只能测直流。交流测量靠整流后实现。</p></blockquote><h2 id="二、仪表准确度等级" tabindex="-1">二、仪表准确度等级 <a class="header-anchor" href="#二、仪表准确度等级" aria-label="Permalink to &quot;二、仪表准确度等级&quot;">​</a></h2><p><strong>准确度等级</strong>表示仪表的测量误差范围,等级数字越小,仪表越精确:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.5 级 &gt; 1.0 级 &gt; 1.5 级 &gt; 2.5 级 &gt; 5.0 级</span></span>
<span class="line"><span>(越靠左越准)</span></span></code></pre></div><ul><li>准确度等级的数字,代表仪表的基本误差(如 2.5 级,基本误差不超过 ±2.5%);</li><li>精密测量用高等级仪表,一般运行监测用较低等级仪表。</li></ul><h2 id="三、量程的选择" tabindex="-1">三、量程的选择 <a class="header-anchor" href="#三、量程的选择" aria-label="Permalink to &quot;三、量程的选择&quot;">​</a></h2><p>量程 = 仪表能测量的最大值。选量程是使用仪表的第一基本功:</p><ol><li><strong>先粗估,后选表</strong>:根据被测值大小,预选量程;</li><li><strong>量程要留余量</strong>:尽量让指针偏转在<strong>刻度盘的 1/2~2/3 区域</strong>(读数最准);</li><li><strong>不可用大量程测小值</strong>:指针偏转太小,读数误差大;</li><li><strong>不能用小量程测大值</strong>:指针打满(过载)会<strong>损坏仪表</strong>。</li></ol><blockquote><p>⚠️ <strong>选量程的原则</strong>:宁大勿小(先大后小),等读数稳定后再换小量程以提高精度。</p></blockquote><h2 id="四、使用仪表的安全要求" tabindex="-1">四、使用仪表的安全要求 <a class="header-anchor" href="#四、使用仪表的安全要求" aria-label="Permalink to &quot;四、使用仪表的安全要求&quot;">​</a></h2><ul><li>测量电压、电流前,先确认仪表量程与被测值匹配;</li><li><strong>测量电流时电流表串联,测量电压时电压表并联</strong>(第 4.2 节详讲);</li><li>在带电设备上测量,要遵守安全间距,使用绝缘工具;</li><li>仪表要定期检定,保持准确。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 准确度等级数字越小越准确(0.5 级比 2.5 级准)。</li><li>✅ 选量程:指针偏转在刻度 1/2~2/3 区域最准确。</li><li>✅ 测量电流串联、测电压并联。</li><li>⚠️ 易混点:等级数字大小与精度高低成<strong>反比</strong>。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>仪表按测量对象分电流表、电压表、功率表、电能表等。</li><li>准确度等级数字越小越精确。</li><li>选量程宁大勿小,读数尽量在 1/2~2/3 刻度区。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)仪表准确度等级的数字越大,表示仪表越精确。( )</li><li>(单选)测量电流时,电流表应与被测电路()。 A. 并联　B. 串联　C. 混联　D. 随意连接</li><li>(判断)测量时,应尽量使指针偏转在刻度盘的中间偏右区域,读数才准确。( )</li><li>(单选)下列属于测量电能(耗电量)的仪表是()。 A. 电压表　B. 电流表　C. 电能表　D. 兆欧表</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>×</strong>。准确度等级数字越小越精确。</li><li><strong>B</strong>。电流表串联、电压表并联。</li><li><strong>√</strong>。指针在刻度 1/2~2/3 区域读数最准。</li><li><strong>C</strong>。电能表(电度表)测量电能。</li></ol></details>`,24)])])}const p=a(e,[["render",r]]);export{u as __pageData,p as default};
